-spec get_ai(integer()) -> [#ai_rule{}].

get_ai(AiId) -> get_ai(AiId, 1, []).

get_ai(AiId, N, Result) ->
    case ai_data:get({AiId, N}) of
        AiRule = #ai_rule{} ->
            get_ai(AiId, N + 1, [AiRule | Result]);
        _ -> lists:reverse(Result)
    end.

